def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("Empty amount")

    sign = '+'
    if s[0] in '+-':
        sign = s[0]
        s = s[1:]

    if not s:
        raise ValueError("Missing amount")

    try:
        value = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError(f"Invalid amount: {dollars}") from exc

    cents = int((value * 100).to_integral_value(rounding=ROUND_HALF_UP))

    if cents == 0:
        sign = '+'

    minor_str = str(abs(cents))
    check = sum(int(ch) for ch in minor_str) % 10

    return f"{sign}{minor_str}#{check}"

