    if s.startswith("-"):
        sign = "-"
        num = s[1:]
    else:
        sign = "+"
        num = s[1:] if s.startswith("+") else s

    if "." in num:
        whole, frac = num.split(".", 1)
        if not whole:
            whole = "0"
        if len(frac) >= 2:
            frac = frac[:2]
        elif len(frac) == 1:
            frac = frac + "0"
        else:
            frac = "00"
        minor = int(whole) * 100 + int(frac)
    else:
        minor = int(num) * 100 if num else 0

    minor_str = str(minor)
    check = sum(int(ch) for ch in minor_str) % 10
    return f"{sign}{minor_str}#{check}"

